import{_ as s,o as t,c as o,ag as a}from"./chunks/framework.DPTJCqgd.js";const r="/deepseek-harness-desktop/assets/harness-desktop-main.DPzz4bzZ.png",n="/deepseek-harness-desktop/assets/harness-desktop-models.DzzrXzFw.png",k=JSON.parse('{"title":"Harness Desktop","description":"A community desktop app for DeepSeek Harness. Bring your models, work in local projects, and extend with plugins.","frontmatter":{"editSource":"docs/user/index.md","editSourceUrl":"https://github.com/Bestbbb/deepseek-harness-desktop/edit/2847c75ea844b05f9d8adca865940856f1286c8c/docs/user/index.md","layout":"page","title":"Harness Desktop","description":"A community desktop app for DeepSeek Harness. Bring your models, work in local projects, and extend with plugins."},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md"}'),i={name:"en/index.md"};function d(p,e,l,c,h,u){return t(),o("div",null,[...e[0]||(e[0]=[a('<main class="dsh-home"><section class="dsh-hero"><div class="dsh-hero-copy"><h1 id="deepseek-harness-for-your-desktop" tabindex="-1">DeepSeek Harness for your desktop. <a class="header-anchor" href="#deepseek-harness-for-your-desktop" aria-label="Permalink to &quot;DeepSeek Harness for your desktop.&quot;">​</a></h1><p>Work in your local projects with your choice of models and a plugin-based agent.</p><div class="dsh-actions"><p><a href="https://github.com/Bestbbb/deepseek-harness-desktop/releases" target="_blank" rel="noreferrer">Download</a> <a href="./guide/quickstart">Read the guide</a></p></div></div><div class="dsh-hero-preview"><p><img src="'+r+'" alt="Harness Desktop conversation workspace before a model is configured"></p></div></section><section class="dsh-models"><div class="dsh-models-copy"><h2 id="choose-your-model" tabindex="-1">Choose your model. <a class="header-anchor" href="#choose-your-model" aria-label="Permalink to &quot;Choose your model.&quot;">​</a></h2><p>Configure DeepSeek, other supported providers, or an OpenAI-compatible gateway. Your provider handles inference and billing.</p><p><a href="./guide/providers">Model setup and authentication</a></p></div><div class="dsh-models-preview"><p><img src="'+n+'" alt="Harness Desktop Models settings with provider configuration controls"></p></div></section><section class="dsh-extension"><h2 id="a-desktop-app-with-room-to-extend" tabindex="-1">A desktop app with room to extend. <a class="header-anchor" href="#a-desktop-app-with-room-to-extend" aria-label="Permalink to &quot;A desktop app with room to extend.&quot;">​</a></h2><p>Harness owns the agent runtime. Tauri supplies the native window and operating-system integration.</p><div class="dsh-extension-grid"><div><h3 id="native-where-it-matters" tabindex="-1">Native where it matters <a class="header-anchor" href="#native-where-it-matters" aria-label="Permalink to &quot;Native where it matters&quot;">​</a></h3><p>System WebView, native menus, keyboard shortcuts, runtime supervision, and diagnostic export. No bundled Electron or Chromium.</p><p><a href="https://github.com/Bestbbb/deepseek-harness-desktop/blob/2847c75ea844b05f9d8adca865940856f1286c8c/apps/desktop/README.md" target="_blank" rel="noreferrer">Desktop architecture</a></p></div><div><h3 id="plugins-at-the-core" tabindex="-1">Plugins at the core <a class="header-anchor" href="#plugins-at-the-core" aria-label="Permalink to &quot;Plugins at the core&quot;">​</a></h3><p>Use Cordis plugins, Agent presets, skills, and MCP integrations. Optional Codex and Claude Code bundles add delegated agents after setup.</p><p><a href="./develop/basic/">Plugin development</a></p></div></div></section><section class="dsh-start"><h2 id="start-with-a-local-project" tabindex="-1">Start with a local project. <a class="header-anchor" href="#start-with-a-local-project" aria-label="Permalink to &quot;Start with a local project.&quot;">​</a></h2><ol><li><strong>Install.</strong> Choose the macOS Apple Silicon or Windows x64 installer from the release assets.</li><li><strong>Connect.</strong> Configure your model provider in Settings, using its supported authentication method.</li><li><strong>Work.</strong> Choose a workspace and an Agent preset, then describe your task.</li></ol><div class="dsh-preview-note"><h3 id="before-you-install" tabindex="-1">Before you install <a class="header-anchor" href="#before-you-install" aria-label="Permalink to &quot;Before you install&quot;">​</a></h3><p>This is a community preview, not an official DeepSeek product. macOS previews are ad-hoc signed and not notarized; Windows previews are unsigned. Check each release&#39;s platform notes and bundled version.</p><p>Local execution is not offline inference. Plugins and external agents run code; review permissions before granting workspace access. Automatic updates are not configured.</p><p><a href="https://github.com/Bestbbb/deepseek-harness-desktop/releases" target="_blank" rel="noreferrer">Download</a></p></div></section><footer class="dsh-home-footer"><p><a href="https://github.com/Bestbbb/deepseek-harness-desktop" target="_blank" rel="noreferrer">Source on GitHub</a></p><p><a href="https://github.com/deepseek-ai/deepseek-harness" target="_blank" rel="noreferrer">Upstream Harness</a></p><p><a href="https://github.com/Bestbbb/deepseek-harness-desktop/blob/2847c75ea844b05f9d8adca865940856f1286c8c/LICENSE" target="_blank" rel="noreferrer">MIT license</a></p></footer></main>',1)])])}const b=s(i,[["render",d]]);export{k as __pageData,b as default};
